INSERT INTO abuse_types (id, category, name, description) VALUES
(1, 'human', 'Violencia física', 'Agresión que causa daño corporal a una persona.'),
(2, 'human', 'Violencia psicológica', 'Actos que causan daño emocional o mental a la víctima.'),
(3, 'human', 'Violencia sexual', 'Cualquier acto sexual realizado sin consentimiento.'),
(4, 'human', 'Violencia intrafamiliar', 'Violencia ejercida entre miembros de un mismo núcleo familiar.'),
(5, 'human', 'Maltrato infantil', 'Abuso físico, psicológico o negligencia hacia un menor de edad.'),
(6, 'human', 'Abandono de persona', 'Desamparo de una persona que depende de cuidados de un tercero.'),
(7, 'human', 'Trata de personas', 'Captación, traslado o explotación de una persona contra su voluntad.'),
(8, 'human', 'Explotación laboral', 'Condiciones de trabajo abusivas o forzadas.'),
(9, 'human', 'Acoso y hostigamiento sexual', 'Conductas de naturaleza sexual no deseadas y reiteradas.'),
(10, 'human', 'Violencia económica o patrimonial', 'Control o privación de recursos económicos de la víctima.'),
(11, 'human', 'Negligencia hacia adulto mayor', 'Falta de atención o cuidados básicos hacia una persona de la tercera edad.'),
(12, 'human', 'Discriminación', 'Trato desigual o excluyente hacia una persona por su condición.'),
(13, 'human', 'Violencia contra la mujer', 'Violencia ejercida contra una mujer por razones de género.'),
(14, 'human', 'Secuestro o privación de libertad', 'Retención de una persona en contra de su voluntad.'),
(15, 'human', 'Amenazas y coacción', 'Intimidación para forzar a la víctima a actuar contra su voluntad.'),
(16, 'animal', 'Maltrato físico', 'Golpes, heridas u otras lesiones infligidas a un animal.'),
(17, 'animal', 'Abandono de animal', 'Dejar a un animal sin cuidado ni posibilidad de subsistencia.'),
(18, 'animal', 'Negligencia alimentaria', 'Privación de alimento o agua a un animal bajo cuidado humano.'),
(19, 'animal', 'Hacinamiento', 'Mantener animales en condiciones de espacio insalubres o insuficientes.'),
(20, 'animal', 'Peleas de animales', 'Organización o participación en peleas entre animales.'),
(21, 'animal', 'Envenenamiento', 'Suministro intencional de sustancias tóxicas a un animal.'),
(22, 'animal', 'Tráfico de especies', 'Comercio ilegal de fauna silvestre o protegida.'),
(23, 'animal', 'Mutilación', 'Amputación o alteración corporal de un animal sin fines veterinarios.'),
(24, 'animal', 'Explotación en espectáculos', 'Uso de animales en shows o eventos bajo maltrato.'),
(25, 'animal', 'Crueldad en sacrificio', 'Sacrificio de animales sin métodos humanitarios.'),
(26, 'animal', 'Zoofilia', 'Abuso sexual cometido contra un animal.'),
(27, 'animal', 'Uso en labores forzadas', 'Sobreexplotación de un animal de carga o trabajo.'),
(28, 'animal', 'Comercio ilegal de mascotas', 'Venta o crianza de animales domésticos sin regulación sanitaria.'),
(29, 'animal', 'Encierro prolongado', 'Confinamiento constante de un animal sin espacio para moverse.');
