INSERT INTO educational_guides (id, title, description, category, pdf_file_url) VALUES
(1, 'Ley para Prevenir, Sancionar y Erradicar la Violencia Intrafamiliar (Decreto 97-96)', 'Marco legal guatemalteco que define la violencia intrafamiliar y establece medidas de protección para las víctimas.', 'prevención - humano', 'https://siteal.iiep.unesco.org/sites/default/files/sit_accion_files/decreto_97-1996.pdf'),
(2, 'Legislación guatemalteca contra la violencia hacia la mujer y la niñez', 'Compendio de leyes vigentes en Guatemala orientadas a la protección de mujeres, niñez y adolescencia frente a la violencia.', 'prevención - humano', 'https://sustainabledevelopment.un.org/content/documents/13085Guatemala_annexes_Beijing20.pdf'),
(3, 'Peores formas de trabajo infantil en Guatemala: avances y retos', 'Informe que describe los esfuerzos y vacíos del Estado de Guatemala para erradicar el trabajo infantil y la explotación laboral.', 'actuación - humano', 'https://www.dol.gov/sites/dolgov/files/ILAB/child_labor_reports/tda2021/Guatemala_Spanish.pdf'),
(4, 'Las instituciones educativas frente al maltrato infantil', 'Estudio sobre cómo las escuelas y comunidades pueden identificar y actuar frente a casos de maltrato infantil.', 'actuación - humano', 'https://www.redalyc.org/pdf/298/29821428007.pdf'),
(5, 'Normativa de la Unidad de Bienestar Animal de Guatemala', 'Disposiciones oficiales de la Unidad de Bienestar Animal (UBA) del MAGA, creada por la Ley de Protección y Bienestar Animal.', 'prevención - animal', 'https://faolex.fao.org/docs/pdf/gua211676.pdf'),
(6, 'Marco regulatorio de la Unidad de Bienestar Animal (Acuerdo Ministerial)', 'Acuerdo ministerial que regula el funcionamiento y vigencia de la Unidad de Bienestar Animal en Guatemala.', 'actuación - animal', 'https://faolex.fao.org/docs/pdf/gua211686.pdf');
