CREATE DATABASE IF NOT EXISTS raysafe;
USE raysafe;

CREATE TABLE roles (
    id          INT AUTO_INCREMENT PRIMARY KEY,
    name        VARCHAR(30) NOT NULL UNIQUE  -- agente, admin
);

CREATE TABLE report_statuses (
    id          INT AUTO_INCREMENT PRIMARY KEY,
    name        VARCHAR(40) NOT NULL UNIQUE,   -- recibida, en revisión, en investigación, cerrada, rechazada
    sort_order  TINYINT NOT NULL               -- orden del flujo del caso, permite pintar una barra de progreso
											   -- sin hardcodear la secuencia en el frontend
);

CREATE TABLE locations (
    id              INT AUTO_INCREMENT PRIMARY KEY,
    city               VARCHAR(100) NOT NULL,    
    department      VARCHAR(100) NOT NULL,
    UNIQUE KEY uq_location (city, department)
);

CREATE TABLE institutions (
    id              INT AUTO_INCREMENT PRIMARY KEY,
    name            VARCHAR(150) NOT NULL,
	category        ENUM('human','animal') NOT NULL,
    type            VARCHAR(80),               -- PNC, refugio animal, etc
    phone           VARCHAR(15),
    email           VARCHAR(150),
    active          BOOLEAN NOT NULL DEFAULT TRUE
);


CREATE TABLE abuse_types (
    id              INT AUTO_INCREMENT PRIMARY KEY,
    category        ENUM('human','animal') NOT NULL,
    name            VARCHAR(80) NOT NULL,
    description     VARCHAR(250)
);

CREATE TABLE users (
    id              INT AUTO_INCREMENT PRIMARY KEY,
    name            VARCHAR(120) NOT NULL,
    email           VARCHAR(150) NOT NULL UNIQUE,
    password  		VARCHAR(250) NOT NULL,
    role_id         INT NOT NULL,
    institution_id  INT NOT NULL,
    active          BOOLEAN NOT NULL DEFAULT TRUE,
    created_at      DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (role_id) REFERENCES roles(id),
    FOREIGN KEY (institution_id) REFERENCES institutions(id)
);

CREATE TABLE reports (
    id                  INT AUTO_INCREMENT PRIMARY KEY,
    public_id           varchar(13) NOT NULL UNIQUE,   -- el id que va tar disponible pa la info general d la denuncia, ej: "DN-8F3K2A1B"
    token_hash          VARCHAR(250) NOT NULL,         -- hash del token secreto que se le va a confiar al q denuncie
    abuse_type_id       INT NOT NULL,
    report_status_id    INT NOT NULL,
    description         TEXT NOT NULL,
    specific_address    VARCHAR(250),
    location_id         INT,
    institution_id      INT,
    risk_level          ENUM('low','medium','high','critical') DEFAULT 'medium',
    notification_email  VARCHAR(150),                -- opcional: contacto para notificaciones
    agent_id            INT,                         -- agente asignado
    created_at          DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at          DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP
						ON UPDATE CURRENT_TIMESTAMP, --  esto es para que cuando se actualice, por default ponga la fecha-hora actual
    FOREIGN KEY (abuse_type_id) REFERENCES abuse_types(id),
    FOREIGN KEY (institution_id) REFERENCES institutions(id),
    FOREIGN KEY (report_status_id) REFERENCES report_statuses(id),
    FOREIGN KEY (location_id) REFERENCES locations(id),
    FOREIGN KEY (agent_id) REFERENCES users(id),
    INDEX idx_public_id (public_id), -- índice para acelerar la búsqueda por folio público,
									 -- a costa de almacenamiento adicional en la base de datos
    INDEX idx_location_type (location_id, abuse_type_id)
);

-- evidencia aportada (al crear la denuncia o después)
CREATE TABLE evidence (
    id              INT AUTO_INCREMENT PRIMARY KEY,
    report_id       INT NOT NULL,
    file_type       VARCHAR(20),         -- imagen, video, audio, documento
    file_url        VARCHAR(500) NOT NULL,
    description     VARCHAR(250),
    uploaded_at     DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (report_id) REFERENCES reports(id) ON DELETE CASCADE
);

-- Historial de cambios de estado, permite construir la línea de tiempo de cada denuncia.
-- Existe por trazabilidad: deja constancia de cada transición del caso.
CREATE TABLE status_history (
    id                  INT AUTO_INCREMENT PRIMARY KEY,
    report_id           INT NOT NULL,
    previous_status_id  INT,
    new_status_id       INT NOT NULL,
    agent_id            INT,
    comment             TEXT,
    date                DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (report_id) REFERENCES reports(id) ON DELETE CASCADE,
    FOREIGN KEY (previous_status_id) REFERENCES report_statuses(id),
    FOREIGN KEY (new_status_id) REFERENCES report_statuses(id),
    FOREIGN KEY (agent_id) REFERENCES users(id)
);

-- notas internas que solo los agentes pueden ver
CREATE TABLE internal_notes (
    id              INT AUTO_INCREMENT PRIMARY KEY,
    report_id       INT NOT NULL,
    agent_id        INT NOT NULL,
    content         TEXT NOT NULL,
    created_at      DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (report_id) REFERENCES reports(id) ON DELETE CASCADE,
    FOREIGN KEY (agent_id) REFERENCES users(id)
);

-- Recursos de ayuda a los que puede acudir la persona que denuncia: líneas de
-- emergencia, centros de apoyo y refugios, filtrables por tipo de abuso o ubicación.
CREATE TABLE help_resources (
    id              INT AUTO_INCREMENT PRIMARY KEY,
    name            VARCHAR(150) NOT NULL,
    type            ENUM('emergency_line','support_center','shelter') NOT NULL,
    abuse_type_id   INT,         -- a qué tipo de abuso aplica, si es null entonces será a todos los tipos
    location_id     INT,
    address         VARCHAR(250),
    phone           VARCHAR(15),
    schedule        VARCHAR(100),
    active          BOOLEAN NOT NULL DEFAULT TRUE,
    FOREIGN KEY (abuse_type_id) REFERENCES abuse_types(id),
    FOREIGN KEY (location_id) REFERENCES locations(id)
);

-- Registro de las notificaciones salientes. Ninguna funcionalidad depende de esta
-- tabla hoy: el envío del correo se puede resolver sin ella. Se conserva para
-- dejar constancia de lo que el sistema envía.
CREATE TABLE email_notifications (
    id              INT AUTO_INCREMENT PRIMARY KEY,
    report_id       INT NOT NULL,
    recipient       VARCHAR(150) NOT NULL,
    event           VARCHAR(80) NOT NULL,     -- cambio_estado, nueva_denuncia, etc.
    send_status     ENUM('pending','sent','failed') NOT NULL DEFAULT 'pending',
    sent_at         DATETIME,
    FOREIGN KEY (report_id) REFERENCES reports(id) ON DELETE CASCADE
);


CREATE TABLE educational_guides (
    id                  INT AUTO_INCREMENT PRIMARY KEY,
    title               VARCHAR(150) NOT NULL,
    description         VARCHAR(500),
    category            VARCHAR(80),          -- prevención, actuación, animal, humano
    pdf_file_url        VARCHAR(500) NOT NULL
);

